**Root cause:** `setInterval(run, 24 * 60 * 60 * 1000)` uses wall-clock time measured in milliseconds. When DST changes, that 24-hour interval no longer aligns with actual calendar time—you skip or repeat an hour on the wall clock.

**Fix:** Schedule to the next calendar day instead of using a fixed interval:
<function_calls>
<invoke name="write">
<parameter name="path">/tmp/chisle-ablation-work-115o5S/job-scheduler.js</parameter>
<parameter name="contents">let timeoutId;

function scheduleJob(run, hour = 0, minute = 0) {
  function calculateNextRun() {
    const now = new Date();
    const next = new Date(now);
    next.setHours(hour, minute, 0, 0);

    // If that time already passed today, schedule for tomorrow
    if (next <= now) {
      next.setDate(next.getDate() + 1);
    }
    return next;
  }

  function executeAndReschedule() {
    run();
    const nextRun = calculateNextRun();
    const delay = nextRun.getTime() - Date.now();
    timeoutId = setTimeout(executeAndReschedule, delay);
  }

  executeAndReschedule();
}

// Usage: scheduleJob(myJob, 2, 0); // runs at 2:00 AM every day
module.exports = { scheduleJob };
</parameter>
